<script setup>
import { onMounted,ref } from 'vue'; import { supabase } from '../lib/supabase'
const counts=ref([]),selected=ref(null),items=ref([]),loading=ref(true),detailsLoading=ref(false),error=ref('');const formatDate=v=>new Date(v).toLocaleDateString('sl-SI')
async function load(){try{const [countsResult,profilesResult]=await Promise.all([supabase.from('inventory_counts').select('*').eq('status','completed').order('completed_at',{ascending:false}),supabase.from('profiles').select('id,full_name')]);if(countsResult.error||profilesResult.error)throw countsResult.error||profilesResult.error;const names=new Map(profilesResult.data.map(p=>[p.id,p.full_name]));counts.value=countsResult.data.map(c=>({...c,creatorName:names.get(c.created_by)||'—'}))}catch{error.value='Zgodovine ni bilo mogoče naložiti. Preverite pravice uporabnika in poskusite ponovno.'}finally{loading.value=false}}
async function open(c){selected.value=c;items.value=[];detailsLoading.value=true;error.value='';try{const {data,error:e}=await supabase.from('inventory_count_items').select('quantity, products(name,unit)').eq('inventory_count_id',c.id);if(e)throw e;items.value=data.sort((a,b)=>(a.products?.name||'').localeCompare(b.products?.name||''))}catch{error.value='Podrobnosti popisa ni bilo mogoče naložiti.'}finally{detailsLoading.value=false}}onMounted(load)
</script>
<template><section class="page history-page"><header><p class="eyebrow">ADMINISTRACIJA</p><h1>Zgodovina popisov</h1><p class="muted">Zaključeni popisi od najnovejšega naprej</p></header><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="center-state">Nalagam zgodovino …</div><template v-else-if="selected"><button class="history-back" @click="selected=null">← Vsi popisi</button><section class="history-detail"><p class="eyebrow">ZAKLJUČEN POPIS</p><h2>{{formatDate(selected.completed_at)}}</h2><p class="muted">Opravil: {{selected.creatorName}}</p></section><div v-if="detailsLoading" class="center-state">Nalagam artikle …</div><div v-else class="history-items"><div v-for="i in items" :key="i.products?.name" class="history-item"><strong>{{i.products?.name}}</strong><span>{{i.quantity}} {{i.products?.unit}}</span></div></div></template><div v-else-if="!counts.length" class="history-empty">Zaključenih popisov še ni.</div><div v-else class="history-list"><button v-for="c in counts" :key="c.id" class="history-row" @click="open(c)"><span class="history-date"><strong>{{formatDate(c.completed_at)}}</strong><small>Opravil: {{c.creatorName}}</small></span><span class="history-status">Zaključen</span><span class="history-arrow">›</span></button></div></section></template>
